'use strict';

// Reads the three original sources, cross-checks each population line,
// computes their sum with Node, writes answer.json, then re-reads and
// verifies the written file.

const fs = require('fs');
const path = require('path');

const SOURCES = [
  { file: 'a.txt', label: 'Alpha' },
  { file: 'b.txt', label: 'Beta' },
  { file: 'c.txt', label: 'Gamma' },
];

const PATTERN = /^([A-Za-z]+) population:\s*(\d+)\s*$/;

const populations = [];
const problems = [];

for (const src of SOURCES) {
  const full = path.resolve(src.file);
  if (!fs.existsSync(full)) {
    problems.push(`missing source: ${src.file}`);
    continue;
  }
  const text = fs.readFileSync(full, 'utf8');
  const lines = text.split(/\r?\n/).filter((l) => l.trim() !== '');
  if (lines.length !== 1) {
    problems.push(`${src.file}: expected exactly 1 non-empty line, found ${lines.length}`);
    continue;
  }
  const m = PATTERN.exec(lines[0].trim());
  if (!m) {
    problems.push(`${src.file}: line does not match "<Label> population: <int>": ${JSON.stringify(lines[0])}`);
    continue;
  }
  const [, label, rawValue] = m;
  if (label !== src.label) {
    problems.push(`${src.file}: expected label ${src.label}, found ${label}`);
  }
  const value = Number.parseInt(rawValue, 10);
  if (!Number.isSafeInteger(value)) {
    problems.push(`${src.file}: population is not a safe integer: ${rawValue}`);
    continue;
  }
  populations.push({ file: src.file, label, value });
}

if (problems.length > 0) {
  console.error('CROSS-CHECK FAILED');
  for (const p of problems) console.error(' - ' + p);
  process.exit(1);
}

if (populations.length !== SOURCES.length) {
  console.error(`CROSS-CHECK FAILED: expected ${SOURCES.length} sources, parsed ${populations.length}`);
  process.exit(1);
}

// Independent second aggregation (reduce vs loop) to cross-check the arithmetic.
let loopSum = 0;
for (const p of populations) loopSum += p.value;
const reduceSum = populations.reduce((acc, p) => acc + p.value, 0);
if (loopSum !== reduceSum) {
  console.error(`CROSS-CHECK FAILED: loop sum ${loopSum} != reduce sum ${reduceSum}`);
  process.exit(1);
}

const total = reduceSum;
const answer = { total };
fs.writeFileSync(path.resolve('answer.json'), JSON.stringify(answer) + '\n', 'utf8');

// Verification of the written artifact.
const raw = fs.readFileSync(path.resolve('answer.json'), 'utf8');
const parsed = JSON.parse(raw);
const checks = [
  ['answer.json parses as JSON', true],
  ['total key present', Object.prototype.hasOwnProperty.call(parsed, 'total')],
  ['total is a number', typeof parsed.total === 'number'],
  ['total is finite integer', Number.isSafeInteger(parsed.total)],
  ['total equals cross-checked sum', parsed.total === total],
  ['only numeric total key present', Object.keys(parsed).length === 1],
];

console.log('Per-source populations (cross-checked):');
for (const p of populations) console.log(`  ${p.file} -> ${p.label} population = ${p.value}`);
console.log(`total = ${total}`);
console.log('answer.json contents: ' + raw.trim());
console.log('Verification:');
for (const [name, ok] of checks) console.log(`  ${ok ? 'PASS' : 'FAIL'} - ${name}`);
if (checks.some(([, ok]) => !ok)) process.exit(1);
console.log('ALL CHECKS PASSED');

