node -e '
const fs=require("fs");
const expect={ "a.txt":"Alpha", "b.txt":"Beta", "c.txt":"Gamma" };
const pat=/^([A-Za-z]+) population:\s*(\d+)\s*$/;
let vals=[],bad=[];
for (const [f,lab] of Object.entries(expect)) {
  const t=fs.readFileSync(f,"utf8");
  const lines=t.split(/\r?\n/).filter(l=>l.trim()!=="");
  if (lines.length!==1) { bad.push(f+": "+lines.length+" non-empty lines"); continue; }
  const m=pat.exec(lines[0].trim());
  if (!m) { bad.push(f+": format mismatch "+JSON.stringify(lines[0])); continue; }
  if (m[1]!==lab) bad.push(f+": label "+m[1]+" != "+lab);
  const all=t.match(/\d+/g)||[];
  if (all.length!==1) bad.push(f+": found "+all.length+" number tokens "+JSON.stringify(all));
  vals.push({f,v:Number(m[2])});
}
const sum=vals.reduce((a,b)=>a+b.v,0);
const raw=fs.readFileSync("answer.json","utf8");
const obj=JSON.parse(raw);
const keys=Object.keys(obj);
console.log("parsed:",JSON.stringify(vals));
console.log("sum:",sum);
console.log("answer.json raw:",JSON.stringify(raw));
console.log("keys:",JSON.stringify(keys));
console.log("total typeof:",typeof obj.total,"value:",obj.total);
console.log("strict equal:",obj.total===sum, "=== 60:", obj.total===60);
console.log("problems:",JSON.stringify(bad));
const ok = bad.length===0 && keys.length===1 && keys[0]==="total" && typeof obj.total==="number" && Number.isInteger(obj.total) && obj.total===sum;
console.log(ok?"VERIFY PASS":"VERIFY FAIL");
process.exit(ok?0:1);
